 except Exception as e:return {'error':type(e).__name__+': '+str(e)[:160]}
def readable(p):
 try:return p.read_text(errors='replace')[:6000]
 except Exception:return ''
r={'workspace':str(root),'host':{'os':platform.platform(),'arch':platform.machine(),'python':sys.version.split()[0],'uid':os.getuid(),'cpu_logical':os.cpu_count()},'files':[],'git':{},'resources':{},'tools':{},'contracts':{},'permissions':{}}
