 for f in files[:100]:
  rel=str((pathlib.Path(base)/f).relative_to(root));r['files'].append(rel)
  if len(r['files'])>=140:break
 if len(r['files'])>=140:break
r['git']['inside']=run(['git','rev-parse','--is-inside-work-tree'])
if r['git']['inside'].get('stdout')=='true':
 for key,cmd in [('status',['git','status','--porcelain=v1','-b']),('branch',['git','branch','--show-current']),('head',['git','rev-parse','HEAD']),('remotes',['git','remote']),('worktree',['git','rev-parse','--show-toplevel'])]:r['git'][key]=run(cmd)
